  ) AS v(id, refs) LOOP
    FOR lang IN SELECT jsonb_object_keys(r.refs) LOOP
      IF EXISTS (SELECT 1 FROM public.blog_posts WHERE id = r.id AND editorial_metadata->>'schema' = 'anacan-blog-editorial-v1'
                  AND editorial_metadata->'locales'->lang IS NULL) THEN
        RAISE EXCEPTION 'EEAT_PARTIAL_LOCALE % %', r.id, lang;
      END IF;
      UPDATE public.blog_posts SET editorial_metadata =
          jsonb_set(coalesce(editorial_metadata, '{}'::jsonb) || jsonb_build_object('locales', coalesce(editorial_metadata->'locales', '{}'::jsonb)),
                    ARRAY['locales', lang],
                    coalesce(editorial_metadata->'locales'->lang, '{}'::jsonb) || jsonb_build_object('references', r.refs->lang))
       WHERE id = r.id AND is_published;
      IF NOT FOUND THEN RAISE EXCEPTION 'EEAT_POST_MISSING %', r.id; END IF;
    END LOOP;
    UPDATE public.blog_posts SET updated_at = now() WHERE id = r.id;
    n := n + 1;
  END LOOP;
  IF n <> 93 THEN RAISE EXCEPTION 'EEAT_COUNT %', n; END IF;
END $m$;
COMMIT;
